SET leaf_message_id = #{row.leafMessageId},
    runtime_session_id = #{row.runtimeSessionId},
    status = 'ACTIVE',
    last_run_id = #{row.lastRunId},
    expires_at = #{row.expiresAt},
    metadata_json = #{row.metadataJson},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND tenant_id = #{row.tenantId}
  AND user_id = #{row.userId}
  AND chat_session_id = #{row.chatSessionId}
  AND provider = 'relay'
